\documentclass[11pt]{article}
\usepackage[margin=2.5cm]{geometry}
\usepackage{amsmath}
\usepackage{tikz}

\title{Preliminary Design of a Rubble Mound Seawall\break for the Dongtan North Shore}
\author{Coastal Engineering Studio --- Group 4}
\date{May 2026}

\begin{document}
\maketitle

\section{Site Conditions}
The north shore faces a fetch of 38~km across the estuary, and the
foreshore consists of soft silty clay with a median grain size of
0.012~mm. Water depths at the proposed alignment range from 1.2~m to
2.6~m relative to the local chart datum, and the tidal range at the
nearest gauge is 3.4~m on spring tides.

\section{Design Water Levels and Waves}
The design high water level is taken as the 50-year return value of
4.15~m, and the corresponding significant wave height at the toe is
$H_s = 2.1$~m with a peak period of $T_p = 5.8$~s. Wave breaking at
the structure is depth limited, and the surf similarity parameter
places the breaking in the plunging regime.

\section{Cross Section}
The preliminary cross section is shown in Figure~\ref{fig:seawall}.
The front slope is 1:2.5 and the crest carries a wave wall founded on
the armour layer. Underlayer and core gradations follow the standard
quarry run curves agreed with the contractor.

\begin{figure}[h]
\centering
\input{fig-seawall.tex}
\caption{Preliminary seawall cross section with a 1:2.5 front slope
and a crest wall at elevation $+6.2$~m.}
\label{fig:seawall}
\end{figure}

\section{Toe Protection}
A toe berm of two layers of 1--2~t rock is placed on a geotextile
filter. The toe depth is checked against the 100-year scour estimate
of 0.8~m, and the berm width is set to four armour units as a
construction tolerance.

\section{Next Steps}
Physical model tests are planned for the autumn term to verify the
overtopping discharge, and the armour stability will be rechecked with
the measured wave spectra from the April buoy campaign.

\end{document}

% Cross section sketch for the seawall report (tikz, unit = m scaled 1:1)
\begin{tikzpicture}[x=1cm,y=1cm]
% seabed
\draw[thick] (0,0) -- (10,0);
% design high water line
\draw[dashed] (0,1.8) -- (10,1.8) node[right]{DHW $+4.15$ m};
% revetment front slope 1:2.5 up to the crest
\draw[very thick] (2,0) -- (4.5,2.2) -- (7.5,2.2)
% crest wave wall
\draw[very thick] (7.5,2.2) -- (7.5,3.0) -- (8.3,3.0) -- (8.3,2.2);
% toe berm
\draw[very thick] (1.4,-0.35) -- (2,0);
\draw[very thick] (1.4,-0.35) -- (3.2,-0.35);
% slope label
\node at (3.0,1.35) {1:2.5};
% crest label
\node at (6.0,2.5) {crest $+6.2$ m};
\end{tikzpicture}

